    "vault.js": "// HARZ Vault v0.1 — Sovereign Storage Protocol core
// Zero dependencies. Pure Node stdlib (crypto, fs, path). Runs unchanged on
// plain Node with NO Cloudflare account, NO npm install.
// Governing law (Rabiu, 2026-10-09): the durable record is the truth.
// A document is not safely stored because an ingestion request succeeded.

'use strict';
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const SCHEMA_VERSION = 'vault-v0.1';

class HarzVault {
  /**
   * @param {string} root       storage root directory (sovereign node path)
   * @param {object} opts       { minFreeBytes: reserve that must remain free after any put }
   */
  constructor(root, opts = {}) {
    this.root = root;
    this.dataDir = path.join(root, 'data');
    this.manifestPath = path.join(root, 'manifest.jsonl');
    this.verifyLogPath = path.join(root, 'verify-log.jsonl');
    this.opts = Object.assign({ minFreeBytes: 256 * 1024 * 1024 }, opts);
    fs.mkdirSync(this.dataDir, { recursive: true });
    if (!fs.existsSync(this.manifestPath)) fs.writeFileSync(this.manifestPath, '');
    if (!fs.existsSync(this.verifyLogPath)) fs.writeFileSync(this.verifyLogPath, '');
    this.index = new Map();          // did -> manifest entry (replayed from disk)
    this._replay();                  // restart recovery law: state comes from the durable record
  }

  sha256(s) { return crypto.createHash('sha256').update(s, 'utf8').digest('hex'); }
  norm(text) { return String(text).toLowerCase().replace(/\s+/g, ' ').trim(); }

  // ---- restart recovery: index is rebuilt from the manifest, never assumed ----
  _replay() {
    const lines = fs.readFileSync(this.manifestPath, 'utf8').split('\n');
    for (const line of lines) {
      if (!line) continue;
      let e;
      try { e = JSON.parse(line); }
      catch { throw new Error('VAULT MANIFEST CORRUPT: unparsable manifest line — refusing to guess'); }
      if (this.index.has(e.did)) throw new Error(`VAULT MANIFEST CORRUPT: duplicate did ${e.did}`);
      this.index.set(e.did, e);
    }
  }

  // ---- capacity law: real free bytes, honest refusal, no hidden walls ----
  freeBytes() {
    try {
      const s = fs.statfsSync(this.dataDir);
      return Number(s.bsize) * Number(s.bavail);
    } catch { return null; } // statfs unavailable → capacity unknown, reported honestly
  }

  /**
   * Durable put. Ack ONLY after: (1) content file fsync'd + atomically renamed,
   * (2) manifest line fsync'd. Idempotent by content identity (did).
   */
  put(doc) {
    const text = doc && Object.prototype.hasOwnProperty.call(doc, 'text') ? String(doc.text) : '';
    if (!('text' in (doc || {}))) throw new Error('put: doc.text required');
    const did = this.sha256(text);
    if (this.index.has(did)) {
      return { ok: true, alreadyStored: true, did, stored: false };
    }
    const size = Buffer.byteLength(text, 'utf8');
    const free = this.freeBytes();
    if (free !== null && free - size < this.opts.minFreeBytes) {
      const err = new Error(
        `CAPACITY REFUSED honestly: free=${free}B need=${size}B reserve=${this.opts.minFreeBytes}B`);
      err.code = 'VAULT_CAPACITY';
      err.freeBytes = free; err.neededBytes = size;
      throw err;
    }
    // durability point 1: content — write temp, fsync, atomic rename (no partial states visible)
    const file = path.join(this.dataDir, did);
    const tmp = file + '.part.' + process.pid;
    const fd = fs.openSync(tmp, 'w');
    try { fs.writeSync(fd, text, 'utf8'); fs.fsyncSync(fd); }
    finally { fs.closeSync(fd); }
    fs.renameSync(tmp, file);

    const now = new Date().toISOString();
    const entry = {
      schema: SCHEMA_VERSION,
      did,
      norm_did: this.sha256(this.norm(text)),
      size,
      url: doc.url ?? null,
      title: doc.title ?? '',
      domain: doc.domain ?? '',
      source: doc.source ?? '',
      language: doc.language ?? '',
      fetched_at: doc.fetched_at ?? now,
      created_at: now,
      ingest_state: 'durable',
      integrity: { algo: 'sha256', verified_at: now, by: 'put' }
    };
    // durability point 2: manifest append + fsync — THEN the ack is allowed
    const mfd = fs.openSync(this.manifestPath, 'a');
    try { fs.writeSync(mfd, JSON.stringify(entry) + '\n'); fs.fsyncSync(mfd); }
    finally { fs.closeSync(mfd); }
    this.index.set(did, entry);
    return { ok: true, alreadyStored: false, did, stored: true };
  }

  /**
   * Hash-verified retrieval. Mismatch or missing file = HARD FAILURE naming the
   * did. Never returns wrong content. Never presents a manifest claim as fact.
   */
  get(did) {
    const entry = this.index.get(did);
    if (!entry) { const e = new Error(`NOT_FOUND: ${did}`); e.code = 'VAULT_NOT_FOUND'; throw e; }
    const file = path.join(this.dataDir, did);
    let text;
    try { text = fs.readFileSync(file, 'utf8'); }
    catch {
      const e = new Error(`DATA_FILE_MISSING: manifest says durable but file for ${did} is gone`);
      e.code = 'VAULT_FILE_MISSING'; throw e;
    }
    const h = this.sha256(text);
    if (h !== did) {
      const e = new Error(`INTEGRITY HARD FAILURE: did ${did} hashes to ${h} — wrong content is never served`);
      e.code = 'VAULT_INTEGRITY'; e.expected = did; e.actual = h; throw e;
    }
    return { did, text, entry, state: this.stateOf(did) };
  }

  /** Recompute hash, record result in the durable verification log. */
  verify(did) {
    const result = { did, at: new Date().toISOString(), ok: false, by: 'verify' };
    try { this.get(did); result.ok = true; }
    catch (e) { result.error = e.code || e.message; }
    const fd = fs.openSync(this.verifyLogPath, 'a');
    try { fs.writeSync(fd, JSON.stringify(result) + '\n'); fs.fsyncSync(fd); }
    finally { fs.closeSync(fd); }
    return result;
  }

  verifyAll(onProgress) {
    let ok = 0, fail = 0; const failures = [];
    for (const did of this.index.keys()) {
      const r = this.verify(did);
      r.ok ? ok++ : (fail++, failures.push(r));
      if (onProgress) onProgress(ok + fail, this.index.size);
    }
    return { ok, fail, failures, total: this.index.size };
  }

  /**
   * Honest state law (HARZ Universal App Contract):
   * LIVE    = hash verified from this node THIS session
   * CACHED  = stored locally, not re-verified now
   * OFFLINE = served from local node with no network verification available
   * STALE   = exists, freshness unguaranteed
   * Cached is never presented as live.
   */
  stateOf(did, opts = {}) {
    const entry = this.index.get(did);
    if (!entry) return 'UNKNOWN';
    const lastVerified = (entry.integrity && entry.integrity.verified_at) || null;
    if (opts.offline || process.env.VAULT_OFFLINE === '1') {
      return lastVerified ? 'OFFLINE(verified ' + String(lastVerified).slice(0, 10) + ')' : 'OFFLINE';
    }
    return lastVerified ? 'LIVE' : 'CACHED';
  }

  /** Honest status: counts, bytes, real free space, capacity headroom. */
  status() {
    let bytes = 0;
    for (const e of this.index.values()) bytes += e.size;
    const free = this.freeBytes();
    return {
      schema: SCHEMA_VERSION,
      node: 'local-sovereign',
      docs: this.index.size,
      content_bytes: bytes,
      free_bytes: free,
      min_reserve_bytes: this.opts.minFreeBytes,
      capacity_truth: free === null ? 'UNKNOWN (statfs unavailable)' :
        (free - this.opts.minFreeBytes > 0 ? `${free - this.opts.minFreeBytes}B headroom` : 'EXHAUSTED — puts will be refused honestly'),
      manifest_path: this.manifestPath
    };
  }

  /** Ordered manifest stream for migration/backup jobs (resumable by cursor). */
  *manifestStream() {
    for (const e of this.index.values()) yield e;
  }
}

module.exports = { HarzVault, SCHEMA_VERSION };
