    "export-corpus.js": "// HARZ Vault v0.1 — Resumable sovereign export job
// Pulls the D1 corpus through the corpus worker's /api/export pipe into the
// local Vault. Resumable, idempotent, honest about offline state.
//
// Node 1 runbook (Termux, never in chat):
//   export HARZ_WAVE_KEY='<key goes here on Node 1 only>'
//   node export-corpus.js https://harz-million-corpus.harz.workers.dev ./vault-root
//
// Interruption is safe at any point: rerun resumes from the durable cursor.

'use strict';
const fs = require('fs');
const path = require('path');
const { HarzVault } = require('./vault');

async function fetchDocs(base, key, after, limit) {
  const url = `${base}/api/export?key=${encodeURIComponent(key)}&after=${after}&limit=${limit}`;
  const res = await fetch(url);
  if (!res.ok) {
    const body = await res.text().catch(() => '');
    throw new Error(`export API ${res.status}: ${body.slice(0, 200)}`);
  }
  return res.json();
}

function durableCursorWrite(cursorPath, cursor) {
  const tmp = cursorPath + '.tmp.' + process.pid;
  const fd = fs.openSync(tmp, 'w');
  try {
    fs.writeSync(fd, JSON.stringify(cursor) + '\n');
    fs.fsyncSync(fd);            // cursor is durable BEFORE we claim progress
  } finally { fs.closeSync(fd); }
  fs.renameSync(tmp, cursorPath);
}

async function main() {
  const [base, rootArg] = process.argv.slice(2);
  if (!base || !rootArg) {
    console.error('usage: node export-corpus.js <corpus-base-url> <vault-root>');
    process.exit(2);
  }
  const key = process.env.HARZ_WAVE_KEY;
  if (!key) {
    console.error('HARZ_WAVE_KEY missing — set it in the environment on this node. Never in chat.');
    process.exit(2);
  }
  const root = path.resolve(rootArg);
  const vault = new HarzVault(root, { minFreeBytes: 1024 * 1024 * 1024 }); // keep 1GB reserve on node
  const cursorPath = path.join(root, 'export-cursor.json');
  let cursor = { last_id: 0, pulled: 0 };
  if (fs.existsSync(cursorPath)) cursor = JSON.parse(fs.readFileSync(cursorPath, 'utf8'));

  console.log(`vault: resuming after doc id ${cursor.last_id} (${cursor.pulled} already pulled)`);
  const LIMIT = 500;
  let totalStored = 0, totalDup = 0, batches = 0;
  while (true) {
    let wave;
    try {
      wave = await fetchDocs(base, key, cursor.last_id, LIMIT);
    } catch (e) {
      const offline = /fetch failed|ENOTFOUND|ECONNREFUSED|ETIMEDOUT/i.test(String(e.message));
      console.error(offline
        ? `OFFLINE truth: cannot reach corpus at ${base}. Local vault stays readable. Rerun when connected — resumes from id ${cursor.last_id}.`
        : `export stopped honestly: ${e.message} — cursor stays at id ${cursor.last_id}`);
      process.exit(offline ? 3 : 1);
    }
    const docs = wave.docs || [];
    if (!docs.length) break;                        // end of corpus
    let stored = 0, dup = 0;
    for (const d of docs) {
      try {
        const r = vault.put({
          text: d.text, url: d.url, title: d.title, domain: '', source: d.source,
          language: d.language, fetched_at: d.fetched_at
        });
        r.stored ? stored++ : dup++;
      } catch (e) {
        if (e.code === 'VAULT_CAPACITY') {
          console.error(`CAPACITY REFUSED honestly at doc id ${cursor.last_id + stored + dup}: ${e.message}`);
          console.error('Cursor is durable. Free space on this node or raise capacity, then rerun.');
          process.exit(4);
        }
        throw e;
      }
    }
    totalStored += stored; totalDup += dup; batches++;
    cursor.last_id = wave.next_after ?? docs[docs.length - 1].id;
    cursor.pulled += docs.length;
    durableCursorWrite(cursorPath, cursor);          // durable BEFORE claiming progress
    if (wave.next_after === null || docs.length < LIMIT) break;
  }
  const st = vault.status();
  console.log(`EXPORT DONE honestly: batches=${batches} stored=${totalStored} alreadyStored(dedup)=${totalDup}`);
  console.log(`vault now: ${st.docs} docs, ${st.content_bytes}B content, free=${st.free_bytes}B, capacity=${st.capacity_truth}`);
  console.log(`cursor: last_id=${cursor.last_id} pulled=${cursor.pulled}`);
}

main().catch(e => { console.error('FATAL:', e.message); process.exit(1); });
