    "tests/run-tests.js": "// HARZ Vault v0.1 — Acceptance tests T1–T10 (sovereign storage ruling 2026-10-09)
// Each test is a death test: it must FAIL LOUDLY, never silently pass.
// Watchdog: no test may hang the suite. Run: node tests/run-tests.js

'use strict';
const fs = require('fs');
const path = require('path');
const os = require('os');
const crypto = require('crypto');
const { spawn, spawnSync } = require('child_process');
const { HarzVault } = require('../vault');

const VAULT = path.resolve(__dirname, '..', 'vault.js');
const EXPORT = path.resolve(__dirname, '..', 'export-corpus.js');

let passed = 0, failed = 0;
const failures = [];
const liveChildren = new Set();
process.on('exit', () => { for (const c of liveChildren) { try { c.kill('SIGKILL'); } catch {} } });

function T(id, name, fn) {
  return new Promise((resolve) => {
    let settled = false;
    const done = (ok, msg) => {
      if (settled) return; settled = true;
      clearTimeout(dog);
      if (ok) { passed++; console.log(`  ${id} PASS  ${name}`); }
      else { failed++; failures.push({ id, name, error: msg }); console.log(`  ${id} FAIL  ${name} :: ${msg}`); }
      resolve();
    };
    const dog = setTimeout(() => done(false, 'WATCHDOG: test exceeded 30s'), 30000);
    try { Promise.resolve(fn()).then(() => done(true)).catch(e => done(false, e.message)); }
    catch (e) { done(false, e.message); }
  });
}
const assert = (c, m) => { if (!c) throw new Error(m || 'assertion failed'); };
const mkRoot = () => fs.mkdtempSync(path.join(os.tmpdir(), 'harz-vault-test-'));

function sampleDocs(n, seedPrefix) {
  const docs = [];
  for (let i = 0; i < n; i++) {
    docs.push({ text: `${seedPrefix || 'sample'} doc ${i}: ${'HARZ sovereign content '.repeat(20)} #${i}\n`, url: `https://example.test/${i}`, title: `Doc ${i}`, source: 'test', language: 'en', fetched_at: new Date().toISOString() });
  }
  return docs;
}

(async () => {
  console.log('HARZ Vault v0.1 acceptance suite — the durable record is the truth\n');

  await T('T1', 'fresh store: 100 docs -> 100 manifest rows, 100 verified, ack after durability', () => {
    const root = mkRoot();
    const v = new HarzVault(root);
    for (const d of sampleDocs(100)) { const r = v.put(d); assert(r.stored, 'put acked without storing'); }
    assert(v.index.size === 100, `expected 100 manifest rows, got ${v.index.size}`);
    const vr = v.verifyAll();
    assert(vr.ok === 100 && vr.fail === 0, `verification: ${vr.ok} ok, ${vr.fail} fail`);
  });

  await T('T2', 'idempotence: re-put same 100 -> 0 new rows, 0 duplicates, honest alreadyStored', () => {
    const root = mkRoot();
    const v = new HarzVault(root);
    const docs = sampleDocs(100);
    docs.forEach(d => v.put(d));
    for (const d of docs) { const r = v.put(d); assert(!r.stored && r.alreadyStored, 're-put created a duplicate or lied'); }
    assert(v.index.size === 100, `duplicate rows exist: ${v.index.size}`);
  });

  await T('T3', 'interruption: SIGKILL mid-batch -> manifest stays consistent, replay survives', () => {
    const root = mkRoot();
    return new Promise((resolve, reject) => {
      const intr = spawn('node', ['-e', `
        const { HarzVault } = require(${JSON.stringify(VAULT)});
        const v = new HarzVault(${JSON.stringify(root)});
        for (let i = 0; i < 50000; i++) v.put({ text: 'interruption corpus doc ' + i + ' ' + Math.random() });
        console.log('ALL DONE');
      `]);
      liveChildren.add(intr);
      let out = '';
      intr.stdout.on('data', d => out += d);
      setTimeout(() => { try { intr.kill('SIGKILL'); } catch {} }, 80);
      intr.on('close', () => {
        try {
          assert(!out.includes('ALL DONE'), 'child finished before kill — test inconclusive');
          const v2 = new HarzVault(root);
          assert(v2.index.size > 0 && v2.index.size < 50000, `unexpected stored count after kill: ${v2.index.size}`);
          const vr = v2.verifyAll();
          assert(vr.fail === 0, `manifest has broken entries after kill: ${vr.fail}`);
          const lines = fs.readFileSync(v2.manifestPath, 'utf8').split('\n').filter(Boolean).length;
          assert(lines === v2.index.size, `manifest lines ${lines} != index size ${v2.index.size} — replay mismatch`);
          resolve();
        } catch (e) { reject(e); }
      });
    });
  });

  await T('T4', 'integrity: flip one byte on disk -> get = HARD FAILURE naming did, never wrong content', () => {
    const root = mkRoot();
    const v = new HarzVault(root);
    const d = sampleDocs(1)[0];
    const { did } = v.put(d);
    const file = path.join(root, 'data', did);
    const buf = fs.readFileSync(file);
    buf[5] = buf[5] === 65 ? 66 : 65;
    fs.writeFileSync(file, buf);
    let threw = null;
    try { v.get(did); } catch (e) { threw = e; }
    assert(threw && threw.code === 'VAULT_INTEGRITY', 'corrupted content was served or wrong error');
    assert(String(threw.message).includes(did), 'failure does not name the did');
  });

  await T('T5', 'restart recovery: new process, same root -> manifest replay, verify all, zero loss', () => {
    const root = mkRoot();
    const v = new HarzVault(root);
    sampleDocs(50).map(d => v.put(d));
    const out = spawnSync('node', ['-e', `
      const { HarzVault } = require(${JSON.stringify(VAULT)});
      const v = new HarzVault(${JSON.stringify(root)});
      const vr = v.verifyAll();
      console.log(JSON.stringify({ docs: v.index.size, ok: vr.ok, fail: vr.fail }));
    `], { encoding: 'utf8' });
    assert(out.status === 0, 'restart process failed: ' + out.stderr);
    const r = JSON.parse(out.stdout.trim().split('\n').pop());
    assert(r.docs === 50 && r.ok === 50 && r.fail === 0, `restart replay: ${JSON.stringify(r)}`);
  });

  await T('T6', 'offline retrieval: no network path -> local docs served with OFFLINE truth', () => {
    const root = mkRoot();
    const v = new HarzVault(root);
    const d = sampleDocs(1)[0];
    const { did } = v.put(d);
    const src = fs.readFileSync(VAULT, 'utf8');
    assert(!/require\(['"]https?['"]|require\(['"]net['"]|[^a-zA-Z.]fetch\(/.test(src),
      'vault core contains a network call path — violates offline law');
    const out = spawnSync('node', ['-e', `
      process.env.VAULT_OFFLINE = '1';
      const { HarzVault } = require(${JSON.stringify(VAULT)});
      const v = new HarzVault(${JSON.stringify(root)});
      const r = v.get(${JSON.stringify(did)});
      console.log(JSON.stringify({ got: r.text.length, state: r.state }));
    `], { encoding: 'utf8' });
    assert(out.status === 0, 'offline retrieval failed: ' + out.stderr);
    const r = JSON.parse(out.stdout.trim().split('\n').pop());
    assert(r.got === d.text.length, 'offline retrieval returned wrong content');
    assert(String(r.state).startsWith('OFFLINE'), `state not OFFLINE: ${r.state}`);
  });

  await T('T7', 'honest states: verification upgrades state to LIVE; labels never overclaim', () => {
    const root = mkRoot();
    const v = new HarzVault(root);
    const d = sampleDocs(1)[0];
    const { did } = v.put(d);
    const out = spawnSync('node', ['-e', `
      const { HarzVault } = require(${JSON.stringify(VAULT)});
      const v = new HarzVault(${JSON.stringify(root)});
      const before = v.stateOf(${JSON.stringify(did)});
      v.get(${JSON.stringify(did)});
      const after = v.stateOf(${JSON.stringify(did)});
      console.log(JSON.stringify({ before, after }));
    `], { encoding: 'utf8' });
    const r = JSON.parse(out.stdout.trim().split('\n').pop());
    assert(typeof r.before === 'string' && r.before.length > 0, 'state before verification must be labeled');
    assert(r.after === 'LIVE', `after session verification state should be LIVE, got ${r.after}`);
  });

  await T('T8', 'capacity truth: reserve exceeds all free bytes -> honest refusal with real numbers', () => {
    const root = mkRoot();
    const probe = new HarzVault(root);
    const realFree = probe.freeBytes();
    assert(realFree !== null && realFree > 0, 'statfs unavailable — capacity law cannot be exercised here');
    const v = new HarzVault(root, { minFreeBytes: realFree + 1024 * 1024 });
    let refused = null;
    try { v.put(sampleDocs(1)[0]); } catch (e) { refused = e; }
    assert(refused && refused.code === 'VAULT_CAPACITY', 'put was not refused at capacity');
    assert(refused.freeBytes > 0, 'refusal did not report real free bytes');
    assert(String(refused.message).includes('honestly'), 'refusal not honest-labeled');
    assert(v.status().capacity_truth.includes('EXHAUSTED'), 'status must tell the capacity truth');
  });

  await T('T9', 'cursor continuation: interrupt export mid-corpus, resume -> no gap, no duplicate', () => {
    const root = mkRoot();
    const N = 1500; // larger than one batch: full 500-doc batches like the real API
    const corpus = [];
    for (let i = 1; i <= N; i++) corpus.push({ id: i, url: `https://m/${i}`, title: `M${i}`, text: `mock corpus doc ${i} ${'sovereign'.repeat(30)} #${i}`, source: 'mock', language: 'en', fetched_at: new Date().toISOString() });
    const http = require('http');
    const server = http.createServer((req, res) => {
      const u = new URL(req.url, 'http://x');
      const after = +(u.searchParams.get('after') || 0);
      const limit = Math.min(+(u.searchParams.get('limit') || 500), 500);
      const docs = corpus.filter(d => d.id > after).slice(0, limit);
      const next = docs.length === limit ? docs[docs.length - 1].id : null;
      res.end(JSON.stringify({ next_after: next, docs }));
    });
    return new Promise((resolve, reject) => {
      server.listen(0, () => {
        const port = server.address().port;
        const env = { ...process.env, HARZ_WAVE_KEY: 'test-key' };
        const cursorPath = path.join(root, 'export-cursor.json');
        const p1 = spawn('node', [EXPORT, `http://127.0.0.1:${port}`, root], { env });
        liveChildren.add(p1);
        // kill as soon as the durable cursor lands mid-corpus
        const poll = setInterval(() => {
          try {
            if (fs.existsSync(cursorPath)) {
              const c = JSON.parse(fs.readFileSync(cursorPath, 'utf8'));
              if (c.last_id > 0 && c.last_id < N) { clearInterval(poll); p1.kill('SIGKILL'); }
            }
          } catch {}
        }, 10);
        const failSafe = setTimeout(() => { clearInterval(poll); try { p1.kill('SIGKILL'); } catch {} }, 20000);
        p1.on('close', () => {
          clearInterval(poll); clearTimeout(failSafe);
          try {
            assert(fs.existsSync(cursorPath), 'no cursor after pass 1 — export never started');
            const c1 = JSON.parse(fs.readFileSync(cursorPath, 'utf8'));
            assert(c1.last_id > 0 && c1.last_id < N, `cursor not mid-corpus: ${c1.last_id} (test inconclusive)`);
            // async spawn: the mock server lives in THIS process, so the event
            // loop must keep running to serve the child (spawnSync would deadlock it)
            const p2 = spawn('node', [EXPORT, `http://127.0.0.1:${port}`, root], { env });
            liveChildren.add(p2);
            let p2out = '', p2err = '';
            p2.stdout.on('data', d => p2out += d); p2.stderr.on('data', d => p2err += d);
            p2.on('close', (code2) => {
              try {
                assert(code2 === 0, 'resume failed: ' + (p2err || p2out || '').slice(-400));
                const c2 = JSON.parse(fs.readFileSync(cursorPath, 'utf8'));
                assert(c2.last_id === N, `cursor ended at ${c2.last_id}, expected ${N}`);
                const v = new HarzVault(root);
                assert(v.index.size === N, `expected ${N} unique docs, got ${v.index.size}`);
